class DeletePasswordWarningView extends ConsumerStatefulWidget {
  const DeletePasswordWarningView({super.key, required this.shouldCreateNew});

  static const String routeName = "/deletePasswordWarning";

  final bool shouldCreateNew;

  @override
  ConsumerState<DeletePasswordWarningView> createState() =>
      _ForgotPasswordDesktopViewState();
}

class _ForgotPasswordDesktopViewState
    extends ConsumerState<DeletePasswordWarningView> {
  bool _deleteInProgress = false;

  Future<bool> _deleteStack() async {
    final appRoot = await StackFileSystem.applicationRootDirectory();

    try {
      // BEAM: stop wallet-api / beam-node, then remove <root>/beam (wallet
      // files and the private node's owner-key-derived data).
      await deleteBeamDataDirectory(appRoot);

      await DB.instance.hive.close();
      if (Platform.isWindows) {
        final xmrDir = Directory("${appRoot.path}/wallets");
        if (xmrDir.existsSync()) {
          await xmrDir.delete(recursive: true);
        }
        final epicDir = Directory("${appRoot.path}/epiccash");
        if (epicDir.existsSync()) {
          await epicDir.delete(recursive: true);
        }

        final mimblewimblecoinDir = Directory(
          "${appRoot.path}/mimblewimblecoin",
        );
        if (mimblewimblecoinDir.existsSync()) {
          await mimblewimblecoinDir.delete(recursive: true);
        }

        await Isar.getInstance("desktopStore")?.close(deleteFromDisk: true);

        await (await StackFileSystem.applicationHiveDirectory()).delete(
          recursive: true,
        );
      } else if (Platform.isLinux) {
        await appRoot.delete(recursive: true);
      } else {
        // macos in ipad mode
        final xmrDir = Directory("${appRoot.path}/wallets");
        if (xmrDir.existsSync()) {
          await xmrDir.delete(recursive: true);
        }
        final epicDir = Directory("${appRoot.path}/epiccash");
        if (epicDir.existsSync()) {
          await epicDir.delete(recursive: true);
        }
        final mimblewimblecoinDir = Directory(
          "${appRoot.path}/mimblewimblecoin",
        );
        if (mimblewimblecoinDir.existsSync()) {
          await mimblewimblecoinDir.delete(recursive: true);
        }

        await (await StackFileSystem.applicationHiveDirectory()).delete(
          recursive: true,
        );
        await (await StackFileSystem.applicationIsarDirectory()).delete(
          recursive: true,
        );
      }

      await DB.instance.init();
    } catch (e, s) {
      Logging.instance.f("$e\n$s", error: e, stackTrace: s);
      return false;
    }

    return true;
  }

  @override
  Widget build(BuildContext context) {
    return DesktopScaffold(
      appBar: DesktopAppBar(
        leading: AppBarBackButton(
          onPressed: () async {
            if (mounted && !_deleteInProgress) {
              Navigator.of(context).pop();
            }
          },
        ),
        isCompactHeight: false,
      ),
      body: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          SizedBox(
            width: 480,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                const AppIcon(width: 100),
                const SizedBox(height: 42),
                Text(context.l10n.loginDeleteTitle, style: STextStyles.desktopH1(context)),
                const SizedBox(height: 24),
                SizedBox(
                  width: 480,
                  child: RichText(
                    textAlign: TextAlign.center,
                    text: TextSpan(
                      children: _boldTagSpans(
                        widget.shouldCreateNew
                            ? context.l10n.loginDeleteWarningCreate(
                              AppConfig.prefix,
                            )
                            : context.l10n.loginDeleteWarningRestore,
                        STextStyles.desktopTextSmall(context),
                        STextStyles.desktopTextSmallBold(context),
                      ),
                    ),
                  ),
                ),
                const SizedBox(height: 48),
                PrimaryButton(
                  label: context.l10n.loginDeleteAndContinue,
                  enabled: !_deleteInProgress,
                  onPressed: () async {
                    final shouldDelete = !_deleteInProgress;
                    setState(() {
                      _deleteInProgress = true;
                    });

                    if (shouldDelete) {
                      unawaited(
                        showFloatingFlushBar(
                          type: FlushBarType.info,
                          message: context.l10n.loginDeleting,
                          context: context,
                        ),
                      );

                      final success = await _deleteStack();

                      if (success) {
                        await showFloatingFlushBar(
                          type: FlushBarType.success,
                          message: appL10n.loginDeleted,
                          context: context,
                        );
                        if (mounted) {
                          await Navigator.of(context).pushNamedAndRemoveUntil(
                            IntroView.routeName,
                            (_) => false,
                          );
                        }
                      } else {
                        await showFloatingFlushBar(
                          type: FlushBarType.warning,
                          message: appL10n.loginDeleteFailed,
                          context: context,
                        );

                        setState(() {
                          _deleteInProgress = false;
                        });
                      }
                    }
                  },
                ),
                const SizedBox(height: 24),
                SecondaryButton(
                  label: context.l10n.loginTakeMeBack,
                  enabled: !_deleteInProgress,
                  onPressed: () {
                    Navigator.of(context).pop();
                  },
                ),
                const SizedBox(height: kDesktopAppBarHeight),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

/// [text] as spans: the parts between <b> and </b> in [bold], the rest in
/// [plain]. The message keeps the bold words inside its whole sentence.
List<TextSpan> _boldTagSpans(String text, TextStyle plain, TextStyle bold) {
  final spans = <TextSpan>[];
  var start = 0;
  for (final m in RegExp(r"<b>(.*?)</b>").allMatches(text)) {
    if (m.start > start) {
      spans.add(TextSpan(text: text.substring(start, m.start), style: plain));
    }
    spans.add(TextSpan(text: m.group(1), style: bold));
    start = m.end;
  }
  if (start < text.length) {
    spans.add(TextSpan(text: text.substring(start), style: plain));
  }
  return spans;
}
